// Independent SYN exercises. Each row gives the answer, the grounds for each
// transition, and an example with different data.
const step = ([claim, reason]) => ({claim, reason});
const exercise = (
 id, chapter, topic, title, prompt, answer, knowledge, hint, steps, example
) => {
 const [statement, claim, reason] = example;
 const exactAnswer = typeof answer==='string' ? answer.split('/').map(Number) : null;
 const part = Array.isArray(answer)
  ? {type:'choice', answer:'0', options:answer.map((text, i) => ({id:String(i),text}))}
  : {type:'number', answer:exactAnswer ? exactAnswer[0]/exactAnswer[1] : answer, rule:'equal'};
 return {
  id:'b-'+id, chapter, title, prompt, hint, knowledge,
  theoryAnchor:'topic-'+topic,
  parts:[{id:'a', label:Array.isArray(answer)?'Выберите ответ':'Введите ответ', ...part}],
  solution:{strategy:hint, steps:steps.map(step), result:Array.isArray(answer)?answer[0]:String(answer)},
  analogous:{title:'Похожий пример', statement, steps:[{claim,reason}]}
 };
};

